/// What finished executions spent. Running executions are counted when they finish.
pub fn spent_usd(&self) -> f64 {
    self.executions
        .values()
        .filter_map(|e| e.result.as_ref())
        .map(|r| r.usage.cost_usd)
        .sum()
}

